// Client script #1: Mandatory Fields on Resolve
function onChange(control, oldValue, newValue, isLoading) {
    if (isLoading) return;
    g_form.setMandatory('close_notes', newValue == 'resolved');
}

// Client script #2: Show Risk Fields for High Priority
